import React from 'react';

import type { CSSObject } from '@emotion/react';

import {
  StyledButton,
  StyledIconContainer,
  StyledLoadingIndicator,
} from './Button.styles';

export type ButtonVariant = 'primary' | 'secondary' | 'destructive';
export type ButtonSize = 'small' | 'medium' | 'large';

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  elevated?: boolean;
  isLoading?: boolean;
  icon?: React.ElementType;
  leading?: boolean;
  trailing?: boolean;
  css?: CSSObject;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      variant = 'primary',
      size = 'medium',
      elevated = false,
      isLoading = false,
      disabled,
      children,
      icon: IconComponent,
      leading,
      trailing,
      css,
      'aria-label': ariaLabel,
      ...props
    },
    forwardedRef,
  ) => {
    const loadingLabel =
      ariaLabel ?? (typeof children === 'string' ? children : 'Loading');

    return (
      <StyledButton
        {...props}
        ref={forwardedRef}
        disabled={disabled}
        onClick={isLoading ? undefined : props.onClick}
        aria-busy={isLoading || undefined}
        aria-label={isLoading ? loadingLabel : ariaLabel}
        $css={css}
        $elevated={elevated}
        $leading={Boolean(leading)}
        $size={size}
        $trailing={Boolean(trailing)}
        $variant={variant}
      >
        {IconComponent && leading && !isLoading && (
          <StyledIconContainer
            $leading
            $size={size}
            $trailing={Boolean(trailing)}
          >
            <IconComponent aria-hidden />
          </StyledIconContainer>
        )}
        {isLoading ? (
          <StyledLoadingIndicator aria-hidden $colorful={variant === 'primary'}>
            <span />
            <span />
            <span />
          </StyledLoadingIndicator>
        ) : (
          children
        )}
        {IconComponent && trailing && !isLoading && (
          <StyledIconContainer
            $leading={Boolean(leading)}
            $size={size}
            $trailing
          >
            <IconComponent aria-hidden />
          </StyledIconContainer>
        )}
      </StyledButton>
    );
  },
);

Button.displayName = 'Button';
